def earliest_after(text, markers, start):
    best = -1
    chosen = ''
    for marker in markers:
        pos = text.find(marker, start)
        if pos >= 0 and (best < 0 or pos < best):
            best = pos
            chosen = marker
    return (best, chosen)

def definition_clause(raw):
    low = raw.casefold()
    pos = low.find('knowledge')
    if pos < 0:
        return ''
    end = source_sentence_dot(raw, pos)
    if end < 0:
        return raw[pos:].strip()
    return raw[pos:end + 1].strip()

def extract_holders(raw, clause):
    low = raw.casefold()
    base = raw.find(clause) if clause else 0
    if base < 0:
        base = 0
    local = clause.casefold() if clause else low
    markers = ['actual knowledge of ', 'of each of ', 'of the individuals ', 'of those individuals ', 'individuals named on ', 'individuals listed in ']
    pos, marker = earliest_after(local, markers, 0)
    if pos < 0:
        means = local.find('means')
        if means >= 0:
            start = means + len('means')
        else:
            start = 0
    else:
        start = pos
        if marker == 'actual knowledge of ':
            start = pos + len('actual knowledge of ')
    ends = []
    for stop in [' in each case', ', in each case', ' after reasonable inquiry', ';', '.', ' (page']:
        value = source_sentence_dot(local, start) if stop == '.' else local.find(stop, start)
        if value >= 0:
            ends.append(value)
    end = min(ends) if ends else len(clause)
    value = clause[start:end].strip(' ,;:')
    if value:
        return value
    return clause.strip()

def extract_scope(clause):
    low = clause.casefold()
    phrase = 'with respect to any matter in question'
    pos = low.find(phrase)
    if pos >= 0:
        return clause[pos:pos + len(phrase)]
    means = low.find('means')
    if means > 0:
        value = clause[:means].strip(' ,;:')
        if value:
            return value
    return clause.strip()

def sentence_at(raw, pos):
    if pos < 0:
        return ''
    start = source_previous_sentence_dot(raw, 0, pos)
    if start < 0:
        start = 0
    else:
        start += 1
    end = source_sentence_dot(raw, pos)
    if end < 0:
        end = len(raw)
    else:
        end += 1
    return raw[start:end].strip()

def exclusion_parts(raw):
    low = raw.casefold()
    start = low.find('with respect to')
    if start < 0:
        start = low.find('intellectual property')
    if start < 0:
        return ('', '')
    block = raw[start:].strip()
    block_low = block.casefold()
    split = -1
    for marker in [' and no knowledge', ' and if not conducted', '; no knowledge', ', no knowledge']:
        pos = block_low.find(marker)
        if pos >= 0 and (split < 0 or pos < split):
            split = pos
    if split < 0:
        return (block, block)
    return (block[:split].strip(' ,;'), block[split:].strip(' ,;'))

def find_actor(raw, start):
    low = raw.casefold()
    markers = ['each of the company parties will', 'each company party will', 'the company parties will not', 'the company parties will', 'the company shall not', 'the company will not', 'the company shall', 'the company will', 'company parties will not', 'company parties will']
    return earliest_after(low, markers, start)

def actor_text(raw, pos, marker):
    if pos < 0:
        return ''
    low = raw.casefold()
    shall = low.find(' shall', pos)
    will = low.find(' will', pos)
    ends = []
    if shall >= 0:
        ends.append(shall)
    if will >= 0:
        ends.append(will)
    end = min(ends) if ends else pos + len(marker)
    return raw[pos:end].strip(' ,;:')

def pandemic_reference(raw):
    low = raw.casefold()
    markers = ['covid-19 measures', 'covid-19 pandemic', 'covid-19', 'covid 19', 'coronavirus', 'pandemic']
    pos, marker = earliest_after(low, markers, 0)
    if pos < 0:
        return ''
    return raw[pos:pos + len(marker)]

def seed_output(inputs):
    seed = inputs.get('source_output', {})
    statements = []
    unresolved = []
    complete = True
    if isinstance(seed, dict):
        for row in seed.get('statements', []):
            if isinstance(row, dict) and isinstance(row.get('term'), list):
                add_statement(statements, row.get('term'), row.get('support_ids', []))
        for value in seed.get('unresolved', []):
            if value not in unresolved:
                unresolved.append(value)
        if seed.get('complete') is False:
            complete = False
    return (statements, unresolved, complete)

def source_sentence_dot(text, start=0):
    pos = text.find('.', start)
    while pos >= 0:
        numeric = pos > 0 and pos + 1 < len(text) and text[pos - 1].isdigit() and text[pos + 1].isdigit()
        if not numeric:
            return pos
        pos = text.find('.', pos + 1)
    return -1

def source_previous_sentence_dot(text, start, end):
    previous = -1
    pos = source_sentence_dot(text, start)
    while pos >= 0 and pos < end:
        previous = pos
        pos = source_sentence_dot(text, pos + 1)
    return previous

